package br.com.erp.pos;
import br.com.erp.auth.*;
import br.com.erp.finance.*;
import br.com.erp.inventory.StockService;
import br.com.erp.shared.Audit;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import static br.com.erp.pos.CashContracts.*;
@Service
public class CashService {
 private final JdbcTemplate db;private final TreasuryService treasury;private final BranchAccess access;private final Audit audit;
 public CashService(JdbcTemplate db,TreasuryService treasury,BranchAccess access,Audit audit){this.db=db;this.treasury=treasury;this.access=access;this.audit=audit;}
 private ResponseStatusException error(HttpStatus s,String m){return new ResponseStatusException(s,m);}
 private String note(String text){String n=text.trim();if(n.length()<5)throw error(HttpStatus.BAD_REQUEST,"Justificativa deve conter cinco caracteres.");return n;}
 private void lock(Actor a){db.queryForObject("SELECT id FROM tenant WHERE id=? FOR UPDATE",UUID.class,a.tenantId());}
 private Terminal terminalRow(java.sql.ResultSet r,int i)throws java.sql.SQLException{return new Terminal(r.getObject("id",UUID.class),r.getObject("branch_id",UUID.class),r.getObject("account_id",UUID.class),r.getObject("warehouse_id",UUID.class),r.getString("code"),r.getString("name"),r.getBoolean("active"),r.getLong("version"));}
 private Terminal findTerminal(Actor a,UUID id){var rows=db.query("SELECT * FROM pos_terminal WHERE tenant_id=? AND id=?",this::terminalRow,a.tenantId(),id);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND,"Terminal não encontrado.");access.requireBranch(a,rows.getFirst().branchId());return rows.getFirst();}
 @Transactional(readOnly=true) public Terminal terminal(Actor a,UUID id){return findTerminal(a,id);}
 @Transactional(readOnly=true) public Map<String,Object> terminals(Actor a,int page,int size){String where=" WHERE t.tenant_id=? AND "+BranchAccess.predicate("t.branch_id");return Map.of("items",db.query("SELECT t.* FROM pos_terminal t"+where+" ORDER BY t.code,t.id LIMIT ? OFFSET ?",this::terminalRow,a.tenantId(),a.tenantId(),a.userId(),size,(long)page*size),"total",db.queryForObject("SELECT COUNT(*) FROM pos_terminal t"+where,Long.class,a.tenantId(),a.tenantId(),a.userId()),"page",page,"size",size);}
 @Transactional public Terminal createTerminal(Actor a,TerminalInput input){
  lock(a);access.requireBranch(a,input.branchId());String code=input.code().toUpperCase(Locale.ROOT),name=input.name().trim();if(name.isEmpty())throw error(HttpStatus.BAD_REQUEST,"Informe o nome do terminal.");String hash=StockService.fingerprint("POS_TERMINAL",input.branchId(),input.accountId(),code,name);
  var old=db.query("SELECT id,fingerprint FROM pos_terminal WHERE tenant_id=? AND request_id=?",(r,i)->Map.entry(r.getObject(1,UUID.class),r.getString(2)),a.tenantId(),input.requestId());if(!old.isEmpty()){if(!hash.equals(old.getFirst().getValue()))throw error(HttpStatus.CONFLICT,"Identificador reutilizado com outros dados.");return findTerminal(a,old.getFirst().getKey());}
  var account=treasury.get(a,input.accountId());if(account.kind()!=TreasuryContracts.Kind.CASH||!account.branchId().equals(input.branchId()))throw error(HttpStatus.BAD_REQUEST,"Terminal exige conta de caixa da mesma filial.");if(db.queryForObject("SELECT COUNT(*) FROM branch WHERE tenant_id=? AND id=? AND active=TRUE",Long.class,a.tenantId(),input.branchId())==0)throw error(HttpStatus.NOT_FOUND,"Filial ativa não encontrada.");
  UUID id=UUID.randomUUID();db.update("INSERT INTO pos_terminal(id,tenant_id,request_id,fingerprint,branch_id,account_id,code,name) VALUES(?,?,?,?,?,?,?,?)",id,a.tenantId(),input.requestId(),hash,input.branchId(),input.accountId(),code,name);audit.record(a,"POS_TERMINAL_CREATED",id);return findTerminal(a,id);
 }
 @Transactional public Terminal active(Actor a,UUID id,Active input){lock(a);var t=findTerminal(a,id);if(t.version()!=input.version())throw error(HttpStatus.CONFLICT,"Terminal alterado. Atualize.");if(t.active()==input.active())return t;if(db.queryForObject("SELECT COUNT(*) FROM pos_cash_session WHERE tenant_id=? AND open_terminal_id=?",Long.class,a.tenantId(),id)>0)throw error(HttpStatus.CONFLICT,"Feche o caixa antes de desativar o terminal.");db.update("UPDATE pos_terminal SET active=?,version=version+1 WHERE tenant_id=? AND id=?",input.active(),a.tenantId(),id);audit.record(a,"POS_TERMINAL_UPDATED",id);return findTerminal(a,id);}
 private Session sessionRow(java.sql.ResultSet r,int i)throws java.sql.SQLException{return new Session(r.getObject("id",UUID.class),r.getObject("terminal_id",UUID.class),r.getObject("branch_id",UUID.class),r.getObject("account_id",UUID.class),r.getObject("operator_id",UUID.class),r.getString("operator_name"),r.getString("terminal_code"),r.getString("terminal_name"),r.getString("status"),r.getLong("version"),r.getBigDecimal("opening_amount"),r.getString("opening_note"),r.getObject("opened_at",OffsetDateTime.class),r.getBigDecimal("expected_amount"),r.getBigDecimal("counted_amount"),r.getBigDecimal("difference"),r.getString("close_note"),r.getObject("closed_by",UUID.class),r.getObject("closed_at",OffsetDateTime.class));}
 private Session find(Actor a,UUID id){var rows=db.query("SELECT s.*,u.name AS operator_name,t.code AS terminal_code,t.name AS terminal_name,CASE WHEN s.status='OPEN' THEN c.balance ELSE s.expected_amount END AS live_expected FROM pos_cash_session s JOIN pos_terminal t ON t.tenant_id=s.tenant_id AND t.id=s.terminal_id JOIN treasury_account c ON c.tenant_id=s.tenant_id AND c.id=s.account_id JOIN app_user u ON u.tenant_id=s.tenant_id AND u.id=s.operator_id WHERE s.tenant_id=? AND s.id=?",(r,i)->{var s=sessionRow(r,i);return new Session(s.id(),s.terminalId(),s.branchId(),s.accountId(),s.operatorId(),s.operatorName(),s.terminalCode(),s.terminalName(),s.status(),s.version(),s.openingAmount(),s.openingNote(),s.openedAt(),r.getBigDecimal("live_expected"),s.countedAmount(),s.difference(),s.closeNote(),s.closedBy(),s.closedAt());},a.tenantId(),id);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND,"Sessão de caixa não encontrada.");var s=rows.getFirst();access.requireBranch(a,s.branchId());return s;}
 private void owner(Actor a,Session s){if(!s.operatorId().equals(a.userId())&&db.queryForObject("SELECT COUNT(*) FROM user_permission WHERE tenant_id=? AND user_id=? AND permission='pos:supervise'",Long.class,a.tenantId(),a.userId())==0)throw error(HttpStatus.FORBIDDEN,"A operação exige o operador do caixa ou um supervisor autorizado.");}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Session get(Actor a,UUID id){return find(a,id);}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Map<String,Object> sessions(Actor a,String status,int page,int size){String where=" WHERE s.tenant_id=? AND "+BranchAccess.predicate("s.branch_id")+" AND (?='' OR s.status=?)";var ids=db.query("SELECT s.id FROM pos_cash_session s"+where+" ORDER BY s.opened_at DESC,s.id LIMIT ? OFFSET ?",(r,i)->r.getObject(1,UUID.class),a.tenantId(),a.tenantId(),a.userId(),status,status,size,(long)page*size);return Map.of("items",ids.stream().map(id->find(a,id)).toList(),"total",db.queryForObject("SELECT COUNT(*) FROM pos_cash_session s"+where,Long.class,a.tenantId(),a.tenantId(),a.userId(),status,status),"page",page,"size",size);}
 @Transactional public Session open(Actor a,Opening input){
  lock(a);var t=findTerminal(a,input.terminalId());String note=note(input.note()),hash=StockService.fingerprint("POS_OPEN",t.id(),a.userId(),input.openingAmount(),note);var old=db.query("SELECT id,fingerprint FROM pos_cash_session WHERE tenant_id=? AND request_id=?",(r,i)->Map.entry(r.getObject(1,UUID.class),r.getString(2)),a.tenantId(),input.requestId());if(!old.isEmpty()){if(!hash.equals(old.getFirst().getValue()))throw error(HttpStatus.CONFLICT,"Identificador de abertura reutilizado com outros dados.");return find(a,old.getFirst().getKey());}
  if(!t.active())throw error(HttpStatus.CONFLICT,"Terminal inativo.");if(db.queryForObject("SELECT COUNT(*) FROM branch WHERE tenant_id=? AND id=? AND active=TRUE",Long.class,a.tenantId(),t.branchId())==0)throw error(HttpStatus.CONFLICT,"Filial inativa.");
  var account=treasury.get(a,t.accountId());if(input.openingAmount().compareTo(account.balance())!=0)throw error(HttpStatus.CONFLICT,"Valor conferido difere do saldo da conta. Regularize a tesouraria antes da abertura.");if(db.queryForObject("SELECT COUNT(*) FROM pos_cash_session WHERE tenant_id=? AND (open_terminal_id=? OR open_operator_id=? OR open_account_id=?)",Long.class,a.tenantId(),t.id(),a.userId(),t.accountId())>0)throw error(HttpStatus.CONFLICT,"Terminal, operador ou conta já possui caixa aberto.");
  UUID id=UUID.randomUUID();db.update("INSERT INTO pos_cash_session(id,tenant_id,request_id,fingerprint,terminal_id,account_id,branch_id,operator_id,opening_amount,opening_note,opened_at,open_terminal_id,open_operator_id,open_account_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,a.tenantId(),input.requestId(),hash,t.id(),t.accountId(),t.branchId(),a.userId(),input.openingAmount(),note,OffsetDateTime.now(ZoneOffset.UTC),t.id(),a.userId(),t.accountId());audit.record(a,"POS_CASH_OPENED",id);return find(a,id);
 }
 private Movement movement(Actor a,UUID id){return db.queryForObject("SELECT * FROM pos_cash_movement WHERE tenant_id=? AND id=?",(r,i)->new Movement(r.getObject("id",UUID.class),r.getObject("session_id",UUID.class),Kind.valueOf(r.getString("kind")),r.getObject("other_account_id",UUID.class),r.getBigDecimal("amount"),r.getString("note"),r.getObject("treasury_operation_id",UUID.class),r.getObject("created_by",UUID.class),r.getObject("created_at",OffsetDateTime.class)),a.tenantId(),id);}
 @Transactional public Movement move(Actor a,UUID id,MovementInput input){
  lock(a);var s=find(a,id);owner(a,s);if(input.otherAccountId()!=null)treasury.get(a,input.otherAccountId());String note=note(input.note()),hash=StockService.fingerprint("POS_CASH_MOVE",id,input.kind(),input.otherAccountId(),input.amount(),note);var old=db.query("SELECT id,fingerprint FROM pos_cash_movement WHERE tenant_id=? AND request_id=?",(r,i)->Map.entry(r.getObject(1,UUID.class),r.getString(2)),a.tenantId(),input.requestId());if(!old.isEmpty()){if(!hash.equals(old.getFirst().getValue()))throw error(HttpStatus.CONFLICT,"Identificador de movimento reutilizado com outros dados.");return movement(a,old.getFirst().getKey());}
  if(!s.status().equals("OPEN"))throw error(HttpStatus.CONFLICT,"Caixa fechado não aceita movimentos.");boolean supply=input.kind()==Kind.SUPPLY;
  var operation=treasury.recordDrawerMovement(a,s.accountId(),new TreasuryContracts.Movement(UUID.randomUUID(),supply?input.otherAccountId():s.accountId(),supply?s.accountId():input.otherAccountId(),input.amount(),note),supply?"POS_SUPPLY":"POS_WITHDRAW");
  UUID movementId=UUID.randomUUID();db.update("INSERT INTO pos_cash_movement(id,tenant_id,request_id,fingerprint,session_id,kind,other_account_id,amount,note,treasury_operation_id,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",movementId,a.tenantId(),input.requestId(),hash,id,input.kind().name(),input.otherAccountId(),input.amount(),note,operation.id(),a.userId(),OffsetDateTime.now(ZoneOffset.UTC));db.update("UPDATE pos_cash_session SET version=version+1 WHERE tenant_id=? AND id=?",a.tenantId(),id);audit.record(a,"POS_CASH_MOVEMENT",movementId);return movement(a,movementId);
 }
 @Transactional public Session close(Actor a,UUID id,Closing input){
  lock(a);var s=find(a,id);owner(a,s);String note=note(input.note()),hash=StockService.fingerprint("POS_CLOSE",id,input.version(),input.countedAmount(),note);
  if(s.status().equals("CLOSED")){String original=db.queryForObject("SELECT close_fingerprint FROM pos_cash_session WHERE tenant_id=? AND id=?",String.class,a.tenantId(),id);UUID key=db.queryForObject("SELECT close_request_id FROM pos_cash_session WHERE tenant_id=? AND id=?",UUID.class,a.tenantId(),id);if(input.requestId().equals(key)&&hash.equals(original))return s;throw error(HttpStatus.CONFLICT,"Caixa já fechado.");}
  if(s.version()!=input.version())throw error(HttpStatus.CONFLICT,"Caixa movimentado por outro acesso. Atualize antes de fechar.");
  db.update("UPDATE pos_cash_session SET status='CLOSED',version=version+1,open_terminal_id=NULL,open_operator_id=NULL,open_account_id=NULL,close_request_id=?,close_fingerprint=?,counted_amount=?,expected_amount=?,difference=?,close_note=?,closed_by=?,closed_at=? WHERE tenant_id=? AND id=?",input.requestId(),hash,input.countedAmount(),s.expectedAmount(),input.countedAmount().subtract(s.expectedAmount()),note,a.userId(),OffsetDateTime.now(ZoneOffset.UTC),a.tenantId(),id);audit.record(a,"POS_CASH_CLOSED",id);return find(a,id);
 }
 @Transactional(readOnly=true) public Map<String,Object> movements(Actor a,UUID id,int page,int size){find(a,id);var ids=db.query("SELECT id FROM pos_cash_movement WHERE tenant_id=? AND session_id=? ORDER BY created_at DESC,id LIMIT ? OFFSET ?",(r,i)->r.getObject(1,UUID.class),a.tenantId(),id,size,(long)page*size);return Map.of("items",ids.stream().map(v->movement(a,v)).toList(),"total",db.queryForObject("SELECT COUNT(*) FROM pos_cash_movement WHERE tenant_id=? AND session_id=?",Long.class,a.tenantId(),id),"page",page,"size",size);}
}
